import { useState } from 'react';
import { Incidents } from './panels/Incidents';
import { AlertRules } from './panels/AlertRules';
import { Runbooks } from './panels/Runbooks';

const PANELS = { incidents: Incidents, alerts: AlertRules, runbooks: Runbooks } as const;

export function App() {
  const [panel, setPanel] = useState<keyof typeof PANELS>('incidents');
  const Panel = PANELS[panel];
  return (
    <div className="app">
      <nav>
        <button onClick={() => setPanel('incidents')}>Incidents</button>
        <button onClick={() => setPanel('alerts')}>Alert rules</button>
        <button onClick={() => setPanel('runbooks')}>Runbooks</button>
      </nav>
      <Panel />
    </div>
  );
}

