import { useEffect, useState } from 'react';
import { getIncidents } from '../api';
import type { Incident } from '../../server/incidents';

export function Incidents() {
  const [incidents, setIncidents] = useState<Incident[]>([]);
  useEffect(() => {
    getIncidents().then(setIncidents);
  }, []);
  return (
    <section>
      <h2>Incidents</h2>
      <table>
        <thead>
          <tr><th>Opened</th><th>Title</th><th>Rule</th><th>Status</th></tr>
        </thead>
        <tbody>
          {incidents.map((i) => (
            <tr key={i.id}>
              <td>{new Date(i.openedAt).toLocaleString()}</td>
              <td>{i.title}</td>
              <td><code>{i.ruleId}</code></td>
              <td>{i.status}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

