import { useEffect, useState } from 'react';
import { getRules } from '../api';
import type { Rule } from '../../server/alerts';

export function AlertRules() {
  const [rules, setRules] = useState<Rule[]>([]);
  useEffect(() => {
    getRules().then(setRules);
  }, []);
  return (
    <section>
      <h2>Alert rules</h2>
      <table>
        <thead>
          <tr><th>Rule</th><th>Condition</th><th>Severity</th></tr>
        </thead>
        <tbody>
          {rules.map((r) => (
            <tr key={r.id}>
              <td>{r.name} <span className="chip">{r.id}</span></td>
              <td><code>{r.metric} {r.op} {r.threshold}</code> for {r.for}</td>
              <td>{r.severity}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

